require 'includes/auth_helpers.php'; require 'includes/db.php'; $isTeam=current_role($pdo)==='admin'; $errors=[];
if($isTeam && $_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['csrf']??null))$errors[]='Your session expired. Please try again.';
 if(isset($_POST['save_promo']) && !$errors){$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$code=strtoupper(trim($_POST['promo_code']??''));$type=$_POST['discount_type']??'percent';$value=(float)($_POST['discount_value']??0);$min=(float)($_POST['minimum_spend']??0);$start=str_replace('T',' ',$_POST['starts_at']??'');$end=str_replace('T',' ',$_POST['ends_at']??'');if(!$name||!$desc||!in_array($type,['percent','fixed','free_item'],true)||$value<0||strtotime($end)<=strtotime($start))$errors[]='Enter a name, description, valid offer, and end time after start time.';else{$stmt=$pdo->prepare("INSERT INTO promotions(name,description,mechanics,promo_code,discount_type,discount_value,max_discount,minimum_spend,starts_at,ends_at,channel,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,'scheduled',?)");$stmt->execute([$name,$desc,trim($_POST['mechanics']??''),$code?:null,$type,$value,($_POST['max_discount']??'')!==''?(float)$_POST['max_discount']:null,$min,$start,$end,trim($_POST['channel']??''),(int)$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO team_inbox_events(event_type,title,message,audience,entity_type,entity_id) VALUES('promo_scheduled',?,?, 'all','promotion',?)")->execute(['Promo scheduled: '.$name,$name.' is scheduled to run from '.$start.' to '.$end.'.',$id]);header('Location: promos.php?saved=1');exit;}}
 if(isset($_POST['promo_status']) && !$errors){$id=(int)$_POST['promo_id'];$status=$_POST['promo_status'];if(in_array($status,['draft','scheduled','active','paused','ended'],true))$pdo->prepare('UPDATE promotions SET status=? WHERE promo_id=?')->execute([$status,$id]);header('Location: promos.php');exit;}
}
$promos=$isTeam?$pdo->query('SELECT * FROM promotions ORDER BY starts_at DESC')->fetchAll():$pdo->query("SELECT * FROM promotions WHERE status='active' AND NOW() BETWEEN starts_at AND ends_at ORDER BY starts_at")->fetchAll();
$metrics=$isTeam?$pdo->query("SELECT p.promo_id, COUNT(r.redemption_id) redemptions, COALESCE(SUM(r.discount_amount),0) discount_total FROM promotions p LEFT JOIN promotion_redemptions r ON r.promo_id=p.promo_id GROUP BY p.promo_id")->fetchAll(PDO::FETCH_UNIQUE):[];
$pageTitle='Promos';require 'includes/header.php'; ?>
