<?=$p['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-secondary">Update</button></form><?php endif;?></article></div><?php endforeach;?></div></main>
<?php if($isTeam):?><div class="modal fade" id="promoModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content order-options-modal"><form method="post"><div class="modal-header"><h2 class="modal-title h5">Create promotion</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="save_promo" value="1"><div class="mb-3"><label class="form-label">Promo name</label><input class="form-control" name="name" required></div><div class="mb-3"><label class="form-label">Customer description</label><textarea class="form-control" name="description" rows="2" required></textarea></div><div class="mb-3"><label class="form-label">Mechanics and terms</label><textarea class="form-control" name="mechanics" rows="2"></textarea></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Discount type</label><select class="form-select" name="discount_type"><option value="percent">Percentage</option><option value="fixed">Fixed amount</option><option value="free_item">Free item</option></select></div><div class="col-md-6 mb-3"><label class="form-label">Value</label><input class="form-control" type="number" min="0" step="0.01" name="discount_value" value="0"></div><div class="col-md-4 mb-3"><label class="form-label">Maximum discount (₱)</label><input class="form-control" type="number" min="0" step="0.01" name="max_discount"></div><div class="col-md-4 mb-3"><label class="form-label">Minimum spend (₱)</label><input class="form-control" type="number" min="0" step="0.01" name="minimum_spend" value="0"></div><div class="col-md-4 mb-3"><label class="form-label">Promo code</label><input class="form-control" name="promo_code"></div><div class="col-md-6 mb-3"><label class="form-label">Starts</label><input class="form-control" type="datetime-local" name="starts_at" required></div><div class="col-md-6 mb-3"><label class="form-label">Ends</label><input class="form-control" type="datetime-local" name="ends_at" required></div><div class="col-md-6 mb-3"><label class="form-label">Channel</label><input class="form-control" name="channel" placeholder="All, GrabFood, in-store"></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-order">Save promo</button></div></form></div></div></div><?php endif;?><?php require 'includes/footer.php'; ?>
